"""Build the editable dashboard as deterministic embedded gzip bytes."""
from pathlib import Path
import gzip

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'dashboard_source.html'
HEADER = ROOT / 'index_html.h'


def main():
    source = SOURCE.read_bytes()
    data = gzip.compress(source, mtime=0)
    lines = [', '.join(f'0x{x:02X}' for x in data[i:i + 16]) for i in range(0, len(data), 16)]
    content = ('#pragma once\n#include <Arduino.h>\n'
               '// Generated by tools/build_dashboard.py\n'
               'static const uint8_t INDEX_HTML_GZ[] PROGMEM = {\n' +
               ',\n'.join(lines) + '\n};\nstatic const size_t INDEX_HTML_GZ_LEN = ' + str(len(data)) + ';\n')
    if not HEADER.is_file() or HEADER.read_text() != content:
        HEADER.write_text(content, encoding='utf8')
    print(f'Dashboard source={len(source)} gzip={len(data)} bytes')


if __name__ == '__main__':
    main()
